// scripts/add-resident-evil.mjs - append the Resident Evil filmography to the
// runtime catalog (src/lib/movies.generated.json).
//
// WHY: the catalog is generated by popularity sweeps, so a franchise whose
// titles are 15+ years old never surfaces on its own. Metadata comes from
// Cinemeta (keyless) and every entry carries its real TMDB id, because the
// watch page resolves all five players through movie.tmdbId - an entry
// without one would render as a card you cannot open.
//
// Idempotent: dedupes against the committed catalog by tmdbId and by slug,
// so re-running it after a catalog regeneration is safe.
//
// Usage: node scripts/add-resident-evil.mjs [--apply]
import fs from 'fs'
import path from 'path'
import { fileURLToPath } from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const ROOT = path.join(__dirname, '..')
const CATALOG = path.join(ROOT, 'src', 'lib', 'movies.generated.json')
const APPLY = process.argv.includes('--apply')
const CINEMETA = 'https://v3-cinemeta.strem.io'

// The theatrical/CG films. Fan productions returned by the search (Red Falls,
// 1.5: Fan Trailer, Reborn) are deliberately left out.
const SLUGS = [
  'tt0120804', // Resident Evil (2002)
  'tt0318627', // Resident Evil: Apocalypse (2004)
  'tt0432021', // Resident Evil: Extinction (2007)
  'tt1174954', // Resident Evil: Degeneration (2008)
  'tt1220634', // Resident Evil: Afterlife (2010)
  'tt1753496', // Resident Evil: Damnation (2012)
  'tt1855325', // Resident Evil: Retribution (2012)
  'tt5776208', // Resident Evil: Vendetta (2017)
  'tt2592614', // Resident Evil: The Final Chapter (2017)
  'tt6920084', // Resident Evil: Welcome to Raccoon City (2021)
  'tt26674627', // Resident Evil: Death Island (2023)
  // tt35538033 (2026) is intentionally absent: it has no IMDb rating yet and
  // every card in the app renders `{rating}/10`, so an unreleased title would
  // ship as a visible "0/10". Add it once it has a real score.
]

const delay = (ms) => new Promise((r) => setTimeout(r, ms))

const slugify = (s) =>
  s.normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/['\u2019]/g, '')
    .replace(/[^A-Za-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .toLowerCase()

function toRuntime(value) {
  const min = parseInt(String(value ?? '').replace(/[^\d]/g, ''), 10)
  if (!Number.isFinite(min) || min <= 0) return ''
  const h = Math.floor(min / 60)
  const m = min % 60
  return h ? `${h}h ${m}m` : `${m}m`
}

async function getMeta(id) {
  const res = await fetch(`${CINEMETA}/meta/movie/${id}.json`)
  if (!res.ok) throw new Error(`${id}: HTTP ${res.status}`)
  const body = await res.json()
  if (!body?.meta) throw new Error(`${id}: no meta`)
  return body.meta
}

const catalog = JSON.parse(fs.readFileSync(CATALOG, 'utf8'))
const seenId = new Set(catalog.movies.map((m) => m.tmdbId).filter(Boolean))
const seenSlug = new Set(catalog.movies.map((m) => m.slug))
const picked = []
const added = []
const skipped = []

for (const id of SLUGS) {
  let meta
  try {
    meta = await getMeta(id)
  } catch (err) {
    skipped.push(`${id} (${err.message})`)
    continue
  }
  await delay(250) // Cinemeta rate-limits; a full run is 12 requests

  const tmdbId = Number(meta.moviedb_id)
  if (!tmdbId) {
    skipped.push(`${meta.name} (no tmdbId)`)
    continue
  }
  if (seenId.has(tmdbId)) {
    skipped.push(`${meta.name} (already in catalog)`)
    continue
  }

  const year = Number.parseInt(String(meta.releaseInfo ?? meta.year ?? ''), 10) || 0
  let slug = slugify(meta.name)
  // Two films share the bare "Resident Evil" title; the year keeps them apart.
  if (seenSlug.has(slug)) slug = `${slug}-${year}`
  if (seenSlug.has(slug)) {
    skipped.push(`${meta.name} ${year} (slug collision)`)
    continue
  }

  const entry = {
    slug,
    title: meta.name,
    year,
    rating: Number.parseFloat(meta.imdbRating) || 0,
    genres: (meta.genres ?? meta.genre ?? []).filter(Boolean),
    runtime: toRuntime(meta.runtime),
    language: 'English',
    director: (meta.director ?? []).filter(Boolean).join(', '),
    cast: (meta.cast ?? []).slice(0, 5).filter(Boolean),
    plot: meta.description ?? '',
    trailerYouTubeId: (meta.trailers ?? []).find((t) => t?.source)?.source ?? '',
    category: year >= 2026 ? 'upcoming' : 'popular',
    tmdbId,
    poster: meta.poster ?? '',
    banner: meta.background ?? '',
  }

  if (!entry.poster || !entry.banner) {
    skipped.push(`${meta.name} (missing art)`)
    continue
  }

  picked.push(entry)
  seenId.add(tmdbId)
  seenSlug.add(slug)
  added.push(`${slug} <- "${entry.title}" ${year} tmdb=${tmdbId} rating=${entry.rating}`)
}

console.log(`Found ${picked.length}, skipped ${skipped.length}`)
for (const line of added) console.log('  ADD  ' + line)
for (const line of skipped) console.log('  SKIP ' + line)

if (APPLY && picked.length) {
  catalog.movies.push(...picked)
  catalog.count = catalog.movies.length
  fs.writeFileSync(CATALOG, JSON.stringify(catalog, null, 2) + '\n')
  console.log(`Wrote ${CATALOG} (${catalog.movies.length} titles)`)
} else if (!APPLY) {
  console.log('Dry run - pass --apply to write')
}
